            // them into the result regardless of this filter) or by
            // passing `--include-meta`. trace:BUG-27 | ai:claude
            let user_asked_for_meta = r#type
                .as_deref()
                .map(|t| t.eq_ignore_ascii_case("meta"))
                .unwrap_or(false);
