    #[allow(clippy::type_complexity)]
    fn empty_maps() -> (
        std::collections::HashMap<String, Vec<String>>,
        std::collections::HashMap<String, String>,
        std::collections::HashMap<String, bool>,
    ) {
        (
            std::collections::HashMap::new(),
            std::collections::HashMap::new(),
            std::collections::HashMap::new(),
        )
    }

